CREATE TABLE IF NOT EXISTS stations (icao TEXT PRIMARY KEY, city TEXT NOT NULL, region TEXT NOT NULL DEFAULT '', cp_name TEXT NOT NULL DEFAULT '', cp_freq TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', alt TEXT);
CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY, loc TEXT NOT NULL REFERENCES stations(icao), cat TEXT NOT NULL CHECK (cat IN ('eat','drink','hotel','act')), name TEXT NOT NULL, area TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, up INTEGER NOT NULL DEFAULT 0, down INTEGER NOT NULL DEFAULT 0, lat REAL, lng REAL, details TEXT, link TEXT);
CREATE INDEX IF NOT EXISTS idx_entries_loc ON entries(loc);
INSERT OR IGNORE INTO stations (icao, city, region, alt) VALUES ('PHNL','Hickam','Oahu, Hawaii',NULL), ('PGUA','Andersen','Guam',NULL), ('RODN','Kadena','Okinawa, Japan',NULL), ('RJTY','Yokota','Tokyo, Japan',NULL), ('RJOI','Iwakuni','Yamaguchi, Japan',NULL), ('RKSO','Osan','Pyeongtaek, Korea',NULL), ('RPLC','Clark','Luzon, Philippines',NULL), ('YPDN','Darwin','Northern Territory, Australia',NULL), ('PWAK','Wake','Wake Island',NULL), ('PAED','Elmendorf','Anchorage, Alaska',NULL), ('KCEF','Westover','Chicopee, Massachusetts',NULL);
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, loc TEXT NOT NULL REFERENCES stations(icao), caption TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, w INTEGER NOT NULL DEFAULT 0, h INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS photo_data (id TEXT NOT NULL, kind TEXT NOT NULL, mime TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY (id, kind));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, title TEXT NOT NULL, date TEXT NOT NULL, all_day INTEGER NOT NULL DEFAULT 0, start_time TEXT NOT NULL DEFAULT '', end_time TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'other', freq TEXT NOT NULL DEFAULT 'none', every INTEGER NOT NULL DEFAULT 1, until TEXT NOT NULL DEFAULT '', exdates TEXT NOT NULL DEFAULT '[]', created TEXT NOT NULL);
